begin;

alter table public.site_events
  add column if not exists artwork_url text not null default '',
  add column if not exists artwork_path text not null default '';

alter table public.site_events
  drop constraint if exists site_events_artwork_path_check;
alter table public.site_events
  add constraint site_events_artwork_path_check check (
    artwork_path = ''
    or artwork_path ~ '^events/artwork/[0-9a-f-]{36}\.(webp|jpg)$'
    or artwork_path in ('static:theme:halloween', 'static:theme:christmas', 'static:theme:easter', 'static:theme:valentines', 'static:theme:new-year', 'static:theme:lunar-new-year', 'static:theme:spring', 'static:theme:summer', 'static:theme:autumn', 'static:theme:earth-day', 'static:theme:world-book-day', 'static:theme:pride', 'static:theme:st-patrick', 'static:theme:day-of-the-dead', 'static:theme:world-childrens-day', 'static:theme:diwali')
  );

alter table public.site_events
  drop constraint if exists site_events_hero_video_path_check;
alter table public.site_events
  add constraint site_events_hero_video_path_check check (
    hero_video_path = ''
    or hero_video_path = 'static:halloween-hero'
    or hero_video_path ~ '^events/[0-9a-f-]{36}\.(mp4|webm)$'
  );

insert into public.site_events (
  slug, name, description, theme_key, starts_at, ends_at, time_zone, activation_mode,
  enabled, manual_active, priority, artwork_url, artwork_path, hero_video_url, hero_video_path, palette, effects
) values
  ('halloween', '{"es":"Halloween","en":"Halloween"}'::jsonb, '{"es":"Una temporada de calabazas, misterio amable y aventuras entre hojas de otoño.","en":"A season of pumpkins, gentle mystery and adventures among autumn leaves."}'::jsonb, 'halloween', '2026-10-12 00:00:00 Europe/Madrid', '2026-11-04 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', true, false, 80, '/images/events/halloween-curileta-pompon-wide.webp', 'static:theme:halloween', '/videos/hero/events/halloween/curileta-halloween.mp4', 'static:halloween-hero', '{"accent":"#f97316","accentStrong":"#c2410c","canvasLight":"#fbf8f1","surfaceLight":"#f5f0e6","textLight":"#202018","canvasDark":"#0b100e","surfaceDark":"#181818","textDark":"#f8f5ec"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["bats","leaves","pumpkins","cornerWebs","cornerSpiders"],"decorationCount":14,"decorationSpeed":"steady","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('christmas', '{"es":"Navidad","en":"Christmas"}'::jsonb, '{"es":"Luces cálidas, nieve y pequeñas historias para compartir en familia.","en":"Warm lights, snow and little stories to share with family."}'::jsonb, 'christmas', '2026-12-20 00:00:00 Europe/Madrid', '2027-01-07 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 65, '/images/events/themes/christmas.svg', 'static:theme:christmas', '', '', '{"accent":"#d96b55","accentStrong":"#a63838","canvasLight":"#f7faf6","surfaceLight":"#edf4ed","textLight":"#17241e","canvasDark":"#081713","surfaceDark":"#181f1b","textDark":"#f2f7f2"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["snow","stars","candles","doves"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('easter', '{"es":"Pascua","en":"Easter"}'::jsonb, '{"es":"Flores, huevos de colores y aventuras de primavera.","en":"Flowers, colorful eggs and springtime adventures."}'::jsonb, 'easter', '2027-03-26 00:00:00 Europe/Madrid', '2027-03-30 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 55, '/images/events/themes/easter.svg', 'static:theme:easter', '', '', '{"accent":"#9b79c8","accentStrong":"#684a95","canvasLight":"#fbf8fb","surfaceLight":"#f4edf4","textLight":"#291e27","canvasDark":"#151218","surfaceDark":"#211b22","textDark":"#fbf6fb"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["flowers","ribbons","stars"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('valentines', '{"es":"Día del amor y la amistad","en":"Valentine’s Day"}'::jsonb, '{"es":"Celebra el cariño, la amistad y los pequeños gestos que unen.","en":"Celebrate care, friendship and the little gestures that bring us together."}'::jsonb, 'valentines', '2027-02-12 00:00:00 Europe/Madrid', '2027-02-16 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 45, '/images/events/themes/valentines.svg', 'static:theme:valentines', '', '', '{"accent":"#dc6b87","accentStrong":"#a83f61","canvasLight":"#fdf7f9","surfaceLight":"#f8edf1","textLight":"#2b1b22","canvasDark":"#1e0f16","surfaceDark":"#281720","textDark":"#fff4f7"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["hearts","flowers","ribbons"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('new-year', '{"es":"Año nuevo","en":"New Year"}'::jsonb, '{"es":"Un comienzo luminoso lleno de deseos, estrellas y nuevos caminos.","en":"A bright new beginning filled with wishes, stars and new paths."}'::jsonb, 'new-year', '2026-12-30 00:00:00 Europe/Madrid', '2027-01-04 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 60, '/images/events/themes/new-year.svg', 'static:theme:new-year', '', '', '{"accent":"#d4a846","accentStrong":"#8b681c","canvasLight":"#faf8f1","surfaceLight":"#f1ecdc","textLight":"#242016","canvasDark":"#12110d","surfaceDark":"#211e16","textDark":"#faf5e8"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["fireworks","stars","ribbons"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('lunar-new-year', '{"es":"Año nuevo lunar","en":"Lunar New Year"}'::jsonb, '{"es":"Faroles, buenos deseos y tiempo para celebrar en comunidad.","en":"Lanterns, good wishes and time to celebrate together."}'::jsonb, 'lunar-new-year', '2027-02-05 00:00:00 Europe/Madrid', '2027-02-21 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 50, '/images/events/themes/lunar-new-year.svg', 'static:theme:lunar-new-year', '', '', '{"accent":"#d63b32","accentStrong":"#9f201b","canvasLight":"#fff8f3","surfaceLight":"#f8e7df","textLight":"#301613","canvasDark":"#1d100e","surfaceDark":"#2b1916","textDark":"#fff3ed"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["lanterns","fireworks","ribbons"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('spring', '{"es":"Primavera","en":"Spring"}'::jsonb, '{"es":"Flores nuevas, colores suaves y curiosidad por todo lo que despierta.","en":"New flowers, soft colors and curiosity about everything waking up."}'::jsonb, 'spring', '2027-03-20 00:00:00 Europe/Madrid', '2027-06-21 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 35, '/images/events/themes/spring.svg', 'static:theme:spring', '', '', '{"accent":"#b66e9c","accentStrong":"#85416d","canvasLight":"#fbf8fb","surfaceLight":"#f4edf4","textLight":"#291e27","canvasDark":"#151218","surfaceDark":"#211b22","textDark":"#fbf6fb"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["flowers","sunflowers","butterflies"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('summer', '{"es":"Verano","en":"Summer"}'::jsonb, '{"es":"Sol, mar y días para imaginar historias al aire libre.","en":"Sun, sea and days for imagining stories outdoors."}'::jsonb, 'summer', '2027-06-21 00:00:00 Europe/Madrid', '2027-09-23 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 30, '/images/events/themes/summer.svg', 'static:theme:summer', '', '', '{"accent":"#e38443","accentStrong":"#a64d26","canvasLight":"#f8fbf8","surfaceLight":"#edf5f0","textLight":"#172725","canvasDark":"#091a1d","surfaceDark":"#142326","textDark":"#f3f8f7"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["ocean","sunflowers","stars"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('autumn', '{"es":"Otoño","en":"Autumn"}'::jsonb, '{"es":"Hojas viajeras, bosques dorados y nuevas aventuras tranquilas.","en":"Falling leaves, golden woods and gentle new adventures."}'::jsonb, 'autumn', '2027-09-22 00:00:00 Europe/Madrid', '2027-12-21 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 30, '/images/events/themes/autumn.svg', 'static:theme:autumn', '', '', '{"accent":"#b77932","accentStrong":"#754318","canvasLight":"#faf7f0","surfaceLight":"#f1e9dc","textLight":"#2b2116","canvasDark":"#17130f","surfaceDark":"#251e17","textDark":"#f8f0e5"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["leaves","acorns","pumpkins"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('earth-day', '{"es":"Día de la Tierra","en":"Earth Day"}'::jsonb, '{"es":"Un día para cuidar nuestro hogar compartido y descubrir la naturaleza.","en":"A day to care for our shared home and discover the natural world."}'::jsonb, 'earth-day', '2027-04-20 00:00:00 Europe/Madrid', '2027-04-24 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 40, '/images/events/themes/earth-day.svg', 'static:theme:earth-day', '', '', '{"accent":"#39875a","accentStrong":"#24613f","canvasLight":"#f6faf5","surfaceLight":"#eaf3e8","textLight":"#17241a","canvasDark":"#0e1710","surfaceDark":"#19251b","textDark":"#f2f7f0"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["leaves","flowers","ocean"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('world-book-day', '{"es":"Día del libro","en":"World Book Day"}'::jsonb, '{"es":"Las historias abren puertas a lugares que todavía no conocemos.","en":"Stories open doors to places we have not discovered yet."}'::jsonb, 'world-book-day', '2027-04-21 00:00:00 Europe/Madrid', '2027-04-25 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 40, '/images/events/themes/world-book-day.svg', 'static:theme:world-book-day', '', '', '{"accent":"#5079a4","accentStrong":"#345878","canvasLight":"#f7f8fb","surfaceLight":"#edf0f6","textLight":"#1c2430","canvasDark":"#10141b","surfaceDark":"#1c222d","textDark":"#f3f5fa"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["books","stars","ribbons"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('pride', '{"es":"Orgullo","en":"Pride"}'::jsonb, '{"es":"Un espacio para celebrar la diversidad, el respeto y la libertad de ser.","en":"A space to celebrate diversity, respect and the freedom to be yourself."}'::jsonb, 'pride', '2027-06-01 00:00:00 Europe/Madrid', '2027-07-01 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 35, '/images/events/themes/pride.svg', 'static:theme:pride', '', '', '{"accent":"#8b65bb","accentStrong":"#60408d","canvasLight":"#faf7fc","surfaceLight":"#f0eaf6","textLight":"#241b2e","canvasDark":"#17111d","surfaceDark":"#241a2d","textDark":"#faf5ff"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["rainbows","stars","ribbons"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('st-patrick', '{"es":"San Patricio","en":"St Patrick’s Day"}'::jsonb, '{"es":"Tréboles, música y un paseo imaginario por paisajes verdes.","en":"Clovers, music and an imaginary walk through green landscapes."}'::jsonb, 'st-patrick', '2027-03-16 00:00:00 Europe/Madrid', '2027-03-19 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 35, '/images/events/themes/st-patrick.svg', 'static:theme:st-patrick', '', '', '{"accent":"#359457","accentStrong":"#22643a","canvasLight":"#f4faf5","surfaceLight":"#e8f3ea","textLight":"#17251b","canvasDark":"#0d1710","surfaceDark":"#18241b","textDark":"#f0f8f1"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["clovers","stars","ribbons"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('day-of-the-dead', '{"es":"Día de Muertos","en":"Day of the Dead"}'::jsonb, '{"es":"Flores, recuerdos entrañables y una celebración colorida de la vida.","en":"Flowers, tender memories and a colorful celebration of life."}'::jsonb, 'day-of-the-dead', '2027-11-01 00:00:00 Europe/Madrid', '2027-11-03 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 45, '/images/events/themes/day-of-the-dead.svg', 'static:theme:day-of-the-dead', '', '', '{"accent":"#d26888","accentStrong":"#973654","canvasLight":"#fff7f5","surfaceLight":"#f6e8e0","textLight":"#2b1b21","canvasDark":"#1a1017","surfaceDark":"#2a1a24","textDark":"#fff3f4"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["flowers","candles","ribbons"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('world-childrens-day', '{"es":"Día Mundial de la Infancia","en":"World Children’s Day"}'::jsonb, '{"es":"Celebramos la imaginación, los derechos y las voces de cada niña y niño.","en":"Celebrating imagination, rights and the voices of every child."}'::jsonb, 'world-childrens-day', '2027-11-19 00:00:00 Europe/Madrid', '2027-11-21 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 40, '/images/events/themes/world-childrens-day.svg', 'static:theme:world-childrens-day', '', '', '{"accent":"#458cb8","accentStrong":"#2c668a","canvasLight":"#f5fafe","surfaceLight":"#eaf3f8","textLight":"#18252d","canvasDark":"#0e161c","surfaceDark":"#19232c","textDark":"#f2f8fc"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["stars","rainbows","books"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb),
  ('diwali', '{"es":"Diwali","en":"Diwali"}'::jsonb, '{"es":"Una celebración de luz, comunidad y esperanza.","en":"A celebration of light, community and hope."}'::jsonb, 'diwali', '2027-10-28 00:00:00 Europe/Madrid', '2027-11-01 23:59:59 Europe/Madrid', 'Europe/Madrid', 'scheduled', false, false, 45, '/images/events/themes/diwali.svg', 'static:theme:diwali', '', '', '{"accent":"#d87428","accentStrong":"#98501d","canvasLight":"#fff8ef","surfaceLight":"#f7ead8","textLight":"#2c2015","canvasDark":"#1b120c","surfaceDark":"#2b1e14","textDark":"#fff4e8"}'::jsonb, '{"decorationsEnabled":true,"motionEnabled":true,"decorations":["lanterns","candles","stars"],"decorationCount":14,"decorationSpeed":"slow","decorationOpacity":0.32,"soundEnabled":false,"scareEffectsEnabled":false}'::jsonb)
on conflict (slug) do update
set name = jsonb_build_object(
      'es', coalesce(nullif(public.site_events.name ->> 'es', ''), excluded.name ->> 'es'),
      'en', coalesce(nullif(public.site_events.name ->> 'en', ''), excluded.name ->> 'en')
    ),
    description = jsonb_build_object(
      'es', coalesce(nullif(public.site_events.description ->> 'es', ''), excluded.description ->> 'es'),
      'en', coalesce(nullif(public.site_events.description ->> 'en', ''), excluded.description ->> 'en')
    ),
    palette = case when public.site_events.palette = '{}'::jsonb then excluded.palette else public.site_events.palette end,
    effects = case when public.site_events.effects = '{}'::jsonb then excluded.effects else public.site_events.effects end,
    artwork_url = case when public.site_events.artwork_url = '' and public.site_events.artwork_path = '' then excluded.artwork_url else public.site_events.artwork_url end,
    artwork_path = case when public.site_events.artwork_url = '' and public.site_events.artwork_path = '' then excluded.artwork_path else public.site_events.artwork_path end,
    hero_video_url = case when excluded.slug = 'halloween' and public.site_events.hero_video_url = '' and public.site_events.hero_video_path = '' then excluded.hero_video_url else public.site_events.hero_video_url end,
    hero_video_path = case when excluded.slug = 'halloween' and public.site_events.hero_video_url = '' and public.site_events.hero_video_path = '' then excluded.hero_video_path else public.site_events.hero_video_path end,
    updated_at = now();

commit;
